function classifyValue(value) {
  if (value === null || value === undefined) return 'missing';
  if (value === '') return 'empty';
  return typeof value;
}

function fullName(first, last = '') {
  const cleanFirst = String(first ?? '').trim();
  if (!cleanFirst) return 'Unknown';
  return `${cleanFirst} ${String(last ?? '').trim()}`.trim();
}

function createCounter() {
  let value = 0;
  return function () { value += 1; return value; };
}

function activeNames(users) {
  return users.filter(user => user.active).map(user => user.name);
}

function moveUser(user, city) {
  return { ...user, profile: { ...(user.profile ?? {}), city } };
}

function updateSubject(items, id, patch) {
  return items.map(item => item.id === id ? { ...item, ...patch } : item);
}

function sumActiveChecks(items) {
  return items.filter(item => item.active).reduce((sum, item) => sum + item.checks, 0);
}

