import { useState } from 'react';
export default function Counter() {
  const [count, setCount] = useState(0);
  function addThree() {
    setCount(current => current + 1);
    setCount(current => current + 1);
    setCount(current => current + 1);
  }
  return <button onClick={addThree}>Aggiungi tre: {count}</button>;
}

export default function SubjectList({ items }) {
  if (items.length === 0) return <p>Nessun soggetto</p>;
  return <ul>{items.map(item => <li key={item.id}>
    <label>{item.name}<input defaultValue={item.name} /></label>
  </li>)}</ul>;
}

import { useState } from 'react';
export default function SubjectForm({ onSave }) {
  const [name, setName] = useState('');
  const [error, setError] = useState('');
  function submit(event) {
    event.preventDefault();
    if (!name.trim()) { setError('Inserisci un nome'); return; }
    onSave(name.trim()); setName(''); setError('');
  }
  return <form noValidate onSubmit={submit}>
    <label htmlFor="name">Nome</label>
    <input id="name" value={name} onChange={event => setName(event.target.value)}
      aria-invalid={Boolean(error)} aria-describedby={error ? 'error' : undefined} />
    {error && <p id="error" role="alert">{error}</p>}
    <button type="submit">Salva</button>
  </form>;
}

import { useState } from 'react';
function Search({ query, onChange }) {
  return <label>Cerca<input value={query} onChange={event => onChange(event.target.value)} /></label>;
}
export default function Archive({ items }) {
  const [query, setQuery] = useState('');
  const visible = items.filter(item => item.name.toLowerCase().includes(query.toLowerCase()));
  return <main><Search query={query} onChange={setQuery} />
    <p>{visible.length} risultati</p><ul>{visible.map(item => <li key={item.id}>{item.name}</li>)}</ul>
  </main>;
}

import { useEffect } from 'react';
export default function PageTitle({ title }) {
  useEffect(() => {
    const previous = document.title; document.title = title;
    return () => { document.title = previous; };
  }, [title]);
  return <h1>{title}</h1>;
}

export default function RemoteState({ result, onRetry }) {
  if (result.status === 'loading') return <p role="status">Caricamento…</p>;
  if (result.status === 'error') return <div><p role="alert">{result.error}</p>
    <button onClick={onRetry}>Riprova</button></div>;
  if (result.status === 'empty') return <p>Nessun soggetto</p>;
  return <ul>{result.data.map(item => <li key={item.id}>{item.name}</li>)}</ul>;
}

function pageFor(pathname) {
  if (pathname === '/subjects') return 'archive';
  if (pathname === '/subjects/new') return 'create';
  return 'not-found';
}

